/* HRM › Recruitment › Configuration (K1–K7): pipeline stages, rejection reasons, skills, survey templates, survey questions. */
(function () {
  const { S, esc, acts, ins, chs } = App; const H = App.H;
  const SECS = [['stages', 'Pipeline stages', 'ri-draggable', () => S.stages.length], ['reasons', 'Rejection reasons', 'ri-close-line', () => S.reasons.length], ['skills', 'Skills', 'ri-star-line', () => S.skills.length], ['surveys', 'Survey templates', 'ri-survey-line', () => S.surveys.length], ['questions', 'Survey questions', 'ri-question-answer-line', () => S.surveys.reduce((a, s) => a + s.questions.length, 0)], ['offer-templates', 'Offer templates', 'ri-file-text-line', () => '–'], ['document-checklists', 'Document checklists', 'ri-checkbox-multiple-line', () => '–']];
  const cs = App.ui.cfg = { q: '' };
  H.route('/hrm/config/:sec', sec => { const s = SECS.find(x => x[0] === sec) || SECS[0]; const v = { stages, reasons, skills, surveys, questions, 'offer-templates': offers, 'document-checklists': docs }[s[0]]();
    return H.frame({ tab: 'config', title: 'Configuration', sub: 'Set up the building blocks every recruitment uses — stages, rejection reasons, skills and application surveys.',
      body: `<div class="hbody"><div class="settings"><nav class="subnav cfg-nav" aria-label="Configuration sections">${SECS.map(([k, t, i, n]) => `<a href="#/hrm/config/${k}" class="${k === s[0] ? 'on' : ''}" ${k === s[0] ? 'aria-current="page"' : ''}><i class="${i}"></i><span class="grow">${t}</span><span class="count">${n()}</span></a>`).join('')}</nav>
        <div class="stack g16" style="min-width:0"><div class="row between wrap g12"><div><h2 class="h6" style="font-size:18px;font-weight:500">${v.title}</h2><p class="caption" style="margin:0">${v.sub}</p></div><div class="row g12 wrap">${v.tools}</div></div>${v.body}</div></div></div>` }); });
  const search = ph => `<div style="width:min(240px,100%)">${App.field('', `<span class="adorn"><i class="ri-search-line"></i></span><input data-in="cfg-q" value="${esc(cs.q)}" placeholder="${ph}" aria-label="${ph}">`, { cls: 'sm' })}</div>`;
  ins['cfg-q'] = el => { cs.q = el.value; const pos = el.selectionStart; App.render(); const i = App.$('[data-in=cfg-q]'); i.focus(); i.setSelectionRange(pos, pos); };
  const match = t => !cs.q || t.toLowerCase().includes(cs.q.toLowerCase());
  window.addEventListener('hashchange', () => { cs.q = ''; });
  const rowActs = (kind, id, name, canDel = true) => `<span class="row-actions"><button class="icon-btn s20" data-act="cfg-edit" data-k="${kind}" data-id="${id}" aria-label="Edit ${esc(name)}"><i class="ri-pencil-line"></i></button><button class="icon-btn s20 danger" data-act="cfg-del" data-k="${kind}" data-id="${id}" aria-label="Delete ${esc(name)}" ${canDel ? '' : 'disabled'}><i class="ri-delete-bin-line"></i></button></span>`;

  const soonSec = (title, sub, icon, lines) => ({ title, sub, tools: '', body: `<div class="cfg-soon"><span class="soon-icon"><i class="${icon}"></i></span><span class="soon-chip"><span class="pulse"></span>Coming soon</span><div class="stack g8" style="max-width:520px">${lines.map(l => `<div class="row g8 top body2"><i class="ri-check-line brand"></i><span>${l}</span></div>`).join('')}</div><a class="btn outlined" href="#" data-act="guide-jump" data-s="setup"><i class="ri-question-line"></i>See it in the Guide</a></div>` });
  const offers = () => soonSec('Offer templates', 'Write your offer letter once and reuse it for every offer.', 'ri-file-text-line', ['Write the letter once, with fill-in words like {{candidate_first_name}}', 'Tick <b>Set as default</b> so new jobs use it', 'Each person’s letter shows their own details when you send an offer']);
  const docs = () => soonSec('Document checklists', 'The list of documents a new starter must send you.', 'ri-checkbox-multiple-line', ['List what every new starter must send — photo ID, a DBS certificate or a professional registration', 'New starters are asked to upload each one', 'You verify or reject each document from their <b>Offer</b> tab']);
  /* stages (K1) */
  const used = id => S.candidates.filter(c => c.stage === id && c.status === 'progress').length + ({ applied: 60, screening: 20, interview: 28, test: 10, offer: 8, hired: 7 }[id] || 0);
  function stages() { return { title: 'Pipeline stages', sub: 'Stages candidates move through. Drag to reorder; the type controls automations like interview scheduling.',
    tools: `<div class="field select sm pillsel"><label>Applies to</label><select data-ch="cfg-applies" aria-label="Applies to"><option>All recruitments (default)</option>${S.recruitments.map(r => `<option>${esc(r.title)}</option>`).join('')}</select></div><button class="btn primary lg" data-act="cfg-add-stage"><i class="ri-add-line"></i>Add stage</button>`,
    body: `<div class="table-card"><div class="legend-row"><span class="caption">Types</span>${['Initial', 'Interview', 'Test', 'Hired', 'Cancelled'].map(t => `<span class="row g4 caption" style="color:var(--text)"><span class="dot ${H.TONE[t]}"></span>${t}</span>`).join('')}</div><div class="table-scroll"><table class="dt"><thead><tr><th style="width:40px"></th><th style="width:40px">#</th><th>Stage</th><th>Type</th><th>Managers</th><th>End stage</th><th>Candidates</th><th></th></tr></thead><tbody>
      ${S.stages.map((s, i) => { const n = used(s.id); return `<tr data-cfgrow="${i}" draggable="true"><td><span class="drag-handle"><i class="ri-draggable"></i></span></td><td><span class="num-dot grey">${i + 1}</span></td><td><b style="font-weight:500">${esc(s.name)}</b></td><td>${H.typeChip(s.type)}</td><td>${H.avs(s.managers)}</td><td>${s.end ? '<span class="good"><i class="ri-check-line"></i> Yes</span>' : '<span class="muted">—</span>'}</td><td class="tnum">${n}</td><td style="text-align:right">${rowActs('stage', s.id, s.name)}</td></tr>`; }).join('')}
      <tr><td></td><td><span class="num-dot grey">${S.stages.length + 1}</span></td><td><b style="font-weight:500">Rejected</b></td><td>${H.typeChip('Cancelled')}</td><td>${H.avs(['nc'])}</td><td><span class="good"><i class="ri-check-line"></i> Yes</span></td><td class="tnum">${S.candidates.filter(c => c.status === 'cancelled').length + 13}</td><td style="text-align:right"><span class="caption">Built in</span></td></tr></tbody></table></div></div>
      <div class="al info"><i class="ri-information-line"></i><div class="txt">Stages with candidates can’t be deleted — move candidates first, or mark the stage inactive.</div></div>` }; }
  chs['cfg-applies'] = el => App.snack(el.value.startsWith('All') ? 'Showing the default pipeline.' : `${el.value} uses the default pipeline — edits here apply to it too.`, 'info');
  let dragRow = null;
  document.addEventListener('dragstart', e => { const r = e.target.closest?.('[data-cfgrow]'); if (r) { dragRow = +r.dataset.cfgrow; e.dataTransfer.setData('text/plain', 'cfg'); } });
  document.addEventListener('dragover', e => { if (dragRow != null && e.target.closest?.('[data-cfgrow]')) e.preventDefault(); });
  document.addEventListener('drop', e => { const r = e.target.closest?.('[data-cfgrow]'); if (dragRow == null || !r) return; e.preventDefault(); const [x] = S.stages.splice(dragRow, 1); S.stages.splice(+r.dataset.cfgrow, 0, x); dragRow = null; App.render(); App.snack('Stage order saved.'); });
  document.addEventListener('dragend', () => { dragRow = null; });

  /* add / edit stage (K2) */
  let sd = null;
  H.addStage = id => { const s = id && H.stage(id); const tIdx = H.stageIdx('test');
    sd = s ? { id, name: s.name, type: s.type, after: H.stageIdx(id) - 1, end: s.end, tried: false } : { id: null, name: '', type: 'Test', after: tIdx >= 0 ? tIdx : S.stages.length - 2, end: false, tried: false };
    H.ms = {}; sd.managers = s ? [...s.managers] : ['nc', 'uk']; drawStage(); };
  function drawStage() { const bad = sd.tried && !sd.name.trim(); const others = S.stages.filter(s => s.id !== sd.id);
    App.dialog(`<div class="dlg-head"><div class="stack g4"><h2 id="dlg-title" class="h6" style="font-size:18px">${sd.id ? 'Edit stage' : 'Add stage'}</h2><p class="caption" style="margin:0">${sd.id ? 'Changes apply to every recruitment using the default pipeline.' : 'New stages are added to every recruitment using the default pipeline.'}</p></div><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>
      <div class="dlg-body"><div class="stack g4"><b class="body2">Stage name <span style="color:var(--error)">*</span></b>${App.field('', `<input data-in="sd" data-k="name" value="${esc(sd.name)}" placeholder="e.g. Reference checks" aria-label="Stage name">`, { cls: 'sm ' + (bad ? 'err' : '') })}${bad ? '<p class="helper err">Give the stage a name</p>' : ''}</div>
        <div class="g2"><div class="stack g4"><b class="body2">Type</b>${App.select('', 'sd-type', ['Initial', 'Interview', 'Test', 'Hired'], sd.type, { cls: 'sm' })}</div><div class="stack g4"><b class="body2">Position</b>${App.select('', 'sd-after', [{ v: '-1', t: 'First' }, ...others.map((s, i) => ({ v: String(i), t: `After “${s.name}”` }))], String(sd.after), { cls: 'sm' })}</div></div>
        <div class="stack g4"><b class="body2">Stage managers <span style="color:var(--error)">*</span></b>${H.msField('', 'sd-mgr', S.staff.filter(s => s.id !== 'ma').map(s => ({ v: s.id, t: s.name })), sd.managers, { err: sd.tried && !sd.managers.length, onChange: v => { sd.managers = v; } })}<p class="helper">Managers are notified when a candidate enters this stage.</p></div>
        <div class="toggle-card bordered"><div><b>End stage</b><span class="caption">Candidates here are considered finished (hired or rejected).</span></div>${App.sw(sd.end, 'data-ch="sd-end"', 'End stage')}</div></div>
      <div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="sd-go">${sd.id ? 'Save changes' : 'Add stage'}</button></div>`, { width: 520 }); }
  ins.sd = el => { sd[el.dataset.k] = el.value; }; chs['sd-type'] = el => { sd.type = el.value; }; chs['sd-after'] = el => { sd.after = +el.value; }; chs['sd-end'] = el => { sd.end = el.checked; };
  acts['cfg-add-stage'] = () => H.addStage();
  acts['sd-go'] = () => { if (!sd.name.trim() || !sd.managers.length) { sd.tried = true; drawStage(); return; }
    const item = sd.id ? Object.assign(H.stage(sd.id), { name: sd.name.trim(), type: sd.type, managers: sd.managers, end: sd.end }) : { id: 'st' + Date.now(), name: sd.name.trim(), type: sd.type, managers: sd.managers, end: sd.end };
    const others = S.stages.filter(s => s !== item); others.splice(sd.after + 1, 0, item); S.stages.splice(0, S.stages.length, ...others);
    App.closeModal(); App.render(); App.snack(sd.id ? `“${item.name}” updated.` : `“${item.name}” added — it now shows on every pipeline board.`); };

  /* rejection reasons (K3, K4) */
  function reasons() { const l = S.reasons.filter(r => match(r.name)); return { title: 'Rejection reasons', sub: 'Shown when a candidate is rejected. Used in reporting and to suggest talent-pool candidates.', tools: `${search('Search reasons')}<button class="btn primary lg" data-act="rr-new"><i class="ri-add-line"></i>Add reason</button>`,
    body: `<div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th>Reason</th><th>Talent pool rule</th><th>Used</th><th></th></tr></thead><tbody>${l.length ? l.map(r => `<tr><td><b style="font-weight:500">${esc(r.name)}</b></td><td>${r.pool ? '<span class="purple"><i class="ri-heart-3-line"></i> Auto-add to talent pool</span>' : '<span class="muted">—</span>'}</td><td>${r.used} candidates</td><td style="text-align:right">${rowActs('reason', r.id, r.name)}</td></tr>`).join('') : '<tr class="empty-row"><td colspan="4">No reasons match.</td></tr>'}</tbody></table></div></div>` }; }
  let rr = null;
  const rrOpen = r => { rr = r ? { id: r.id, name: r.name, pool: r.pool, tried: false } : { id: null, name: '', pool: true, tried: false }; drawRR(); };
  function drawRR() { const bad = rr.tried && !rr.name.trim();
    App.dialog(`<div class="dlg-head"><h2 id="dlg-title" class="h6" style="font-size:18px">${rr.id ? 'Edit rejection reason' : 'Add rejection reason'}</h2><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>
      <div class="dlg-body"><div class="stack g4"><b class="body2">Reason <span style="color:var(--error)">*</span></b>${App.field('', `<input data-in="rr" value="${esc(rr.name)}" placeholder="e.g. Relocating — may reapply" aria-label="Reason">`, { cls: 'sm ' + (bad ? 'err' : '') })}${bad ? '<p class="helper err">Add the reason</p>' : ''}</div>
        <div class="toggle-card bordered"><div><b>Suggest talent pool</b><span class="caption">Offer to add candidates rejected with this reason to a pool</span></div>${App.sw(rr.pool, 'data-ch="rr-pool"', 'Suggest talent pool')}</div>
        ${rr.pool ? '<div class="hint-box purple"><i class="ri-heart-3-line"></i><span>Great for “strong but not this time” reasons, like vacancy filled.</span></div>' : ''}</div>
      <div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button>${rr.id ? '' : '<button class="btn outlined lg" data-act="rr-go" data-again="1">Save &amp; add another</button>'}<button class="btn primary lg" data-act="rr-go">Save</button></div>`, { width: 480 }); }
  acts['rr-new'] = () => rrOpen(null); ins.rr = el => { rr.name = el.value; }; chs['rr-pool'] = el => { rr.pool = el.checked; drawRR(); };
  acts['rr-go'] = el => { if (!rr.name.trim()) { rr.tried = true; drawRR(); return; } const r = S.reasons.find(x => x.id === rr.id); if (r) Object.assign(r, { name: rr.name.trim(), pool: rr.pool }); else S.reasons.push({ id: 'rr' + Date.now(), name: rr.name.trim(), pool: rr.pool, used: 0 });
    const name = rr.name.trim(); if (el.dataset.again) { rrOpen(null); App.render(); rrOpen(null); } else { App.closeModal(); App.render(); } App.snack(`“${name}” saved.`); };

  /* skills (K5) */
  function skills() { const l = S.skills.filter(s => match(s.name)); return { title: 'Skills', sub: 'Tag recruitments with the skills you’re hiring for. Used to match CVs and talent-pool candidates.', tools: `${search('Search skills')}<button class="btn primary lg" data-act="sk-new"><i class="ri-add-line"></i>Add skill</button>`,
    body: `<div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th>Skill</th><th>Used in recruitments</th><th></th></tr></thead><tbody>${l.length ? l.map(s => { const n = S.recruitments.filter(r => r.skills.includes(s.name)).length; return `<tr><td><b style="font-weight:500">${esc(s.name)}</b></td><td>${n} recruitment${n === 1 ? '' : 's'}</td><td style="text-align:right">${rowActs('skill', s.id, s.name)}</td></tr>`; }).join('') : '<tr class="empty-row"><td colspan="3">No skills match.</td></tr>'}</tbody></table></div></div>` }; }
  let sk = null;
  const skOpen = s => { sk = { id: s ? s.id : null, name: s ? s.name : '', tried: false }; App.dialog(`<div class="dlg-head"><h2 id="dlg-title" class="h6" style="font-size:18px">${sk.id ? 'Edit skill' : 'Add skill'}</h2><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div><div class="dlg-body">${App.field('Skill', `<input data-in="sk" value="${esc(sk.name)}" placeholder="e.g. Minor surgery">`, { req: true })}</div><div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="sk-go">Save</button></div>`, { width: 440 }); };
  acts['sk-new'] = () => skOpen(null); ins.sk = el => { sk.name = el.value; };
  acts['sk-go'] = () => { if (!sk.name.trim()) { App.$('[data-in=sk]').closest('.field').classList.add('err'); return; } const s = S.skills.find(x => x.id === sk.id);
    if (s) { S.recruitments.forEach(r => { r.skills = r.skills.map(x => x === s.name ? sk.name.trim() : x); }); s.name = sk.name.trim(); } else S.skills.push({ id: 'sk' + Date.now(), name: sk.name.trim() }); App.closeModal(); App.render(); App.snack('Skill saved.'); };

  /* survey templates (K6) + questions (K7) */
  function surveys() { const l = S.surveys.filter(s => match(s.name)); return { title: 'Survey templates', sub: 'Question sets candidates answer when they apply. Attach one per recruitment.', tools: `${search('Search templates')}<button class="btn primary lg" data-act="sv-new"><i class="ri-add-line"></i>New template</button>`,
    body: l.map(s => { const by = S.recruitments.filter(r => r.survey === s.id).map(r => r.title); return `<section class="tpl-card"><div class="pool-h"><span class="fic sm"><i class="ri-survey-line"></i></span><b class="grow" style="font-weight:500;font-size:15px">${esc(s.name)} <span class="chip sm" style="margin-left:6px">${s.questions.length} questions</span></b><span class="caption">Used by: ${by.length ? esc(by.join(', ')) : 'Not attached'}</span><button class="icon-btn s20" data-act="sv-menu" data-id="${s.id}" data-menu-anchor aria-label="Template options"><i class="ri-more-2-fill"></i></button><button class="icon-btn s20" data-act="sv-tog" data-id="${s.id}" aria-expanded="${s.open}" aria-label="${s.open ? 'Collapse' : 'Expand'}"><i class="${s.open ? 'ri-arrow-up-s-line' : 'ri-arrow-down-s-line'}"></i></button></div>
      ${s.open ? `<div>${s.questions.map((q, i) => qRow(s, q, i)).join('')}<button class="add-lead" style="margin:8px 16px" data-act="q-new" data-id="${s.id}"><i class="ri-add-line"></i>Add question</button></div>` : ''}</section>`; }).join('') || '<div class="empty"><p>No templates match.</p></div>' }; }
  const qRow = (s, q, i, tpl) => `<div class="q-row"><span class="drag-handle"><i class="ri-draggable"></i></span><span class="num-dot grey">${i + 1}</span><span class="grow">${esc(q.q)}</span>${tpl ? `<span class="caption">${esc(s.name)}</span>` : ''}<span class="chip sm filled t-grey">${esc(q.type)}</span><span class="caption req ${q.required ? '' : 'opt'}">${q.required ? 'Required' : 'Optional'}</span><button class="icon-btn s20" data-act="q-edit" data-id="${s.id}" data-i="${i}" aria-label="Edit question"><i class="ri-pencil-line"></i></button><button class="icon-btn s20 danger" data-act="q-del" data-id="${s.id}" data-i="${i}" aria-label="Delete question"><i class="ri-delete-bin-line"></i></button></div>`;
  function questions() { const all = S.surveys.flatMap(s => s.questions.map((q, i) => [s, q, i])).filter(([s, q]) => match(q.q)); return { title: 'Survey questions', sub: 'Every question across your templates.', tools: `${search('Search questions')}<button class="btn primary lg" data-act="q-new" data-id="${S.surveys[0]?.id}"><i class="ri-add-line"></i>Add question</button>`,
    body: `<section class="tpl-card">${all.map(([s, q, i]) => qRow(s, q, i, true)).join('') || '<div class="empty"><p>No questions match.</p></div>'}</section>` }; }
  acts['sv-tog'] = el => { const s = S.surveys.find(x => x.id === el.dataset.id); s.open = !s.open; App.render(); };
  acts['sv-menu'] = el => { const s = S.surveys.find(x => x.id === el.dataset.id);
    App.menu(el, `<button data-pick="preview" class="sel"><i class="ri-eye-line"></i>Preview</button><button data-pick="add"><i class="ri-add-line"></i>Add question</button><button data-pick="edit"><i class="ri-pencil-line"></i>Edit template</button><hr><button class="danger" data-pick="del"><i class="ri-delete-bin-line"></i>Delete template</button>`, v => {
      if (v === 'preview') App.dialog(`${App.dlgHead(esc(s.name), 'What candidates see when they apply')}<div class="dlg-body">${s.questions.map(q => `<div class="stack g8"><span class="body2">${esc(q.q)}${q.required ? ' <b style="color:var(--error)">*</b>' : ''}</span>${q.type === 'Yes / No' ? `<div class="seg grey sm" style="align-self:flex-start"><button>Yes</button><button>No</button></div>` : q.type === 'Multiple choice' ? (q.options || []).map(o => `<label class="cbx"><input type="radio" name="pv${esc(q.q.length)}">${esc(o)}</label>`).join('') : App.field('', '<textarea rows="2" placeholder="Your answer" aria-label="Answer"></textarea>', { cls: 'multi' })}</div>`).join('')}</div><div class="dlg-foot"><button class="btn primary lg" data-act="close-modal">Close</button></div>`, { width: 600 });
      if (v === 'add') qOpen(s.id); if (v === 'edit') svOpen(s);
      if (v === 'del') { if (S.recruitments.some(r => r.survey === s.id)) { App.snack('Detach it from its recruitments before deleting it.', 'error'); return; } S.surveys = S.surveys.filter(x => x !== s); App.render(); App.snack(`Template “${s.name}” deleted.`); } }, { width: 220 }); };
  let sv = null;
  const svOpen = s => { sv = { id: s ? s.id : null, name: s ? s.name : '' }; App.dialog(`<div class="dlg-head"><h2 id="dlg-title" class="h6" style="font-size:18px">${sv.id ? 'Edit template' : 'New template'}</h2><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div><div class="dlg-body">${App.field('Template name', `<input data-in="sv" value="${esc(sv.name)}" placeholder="e.g. Pharmacy skills">`, { req: true })}</div><div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="sv-go">${sv.id ? 'Save' : 'Create template'}</button></div>`, { width: 460 }); };
  acts['sv-new'] = () => svOpen(null); ins.sv = el => { sv.name = el.value; };
  acts['sv-go'] = () => { if (!sv.name.trim()) { App.$('[data-in=sv]').closest('.field').classList.add('err'); return; } const s = S.surveys.find(x => x.id === sv.id); if (s) s.name = sv.name.trim(); else { const n = { id: 'sv' + Date.now(), name: sv.name.trim(), open: true, questions: [] }; S.surveys.push(n); App.closeModal(); App.render(); qOpen(n.id); App.snack('Template created — add its first question.', 'info'); return; } App.closeModal(); App.render(); };
  let qd = null;
  const qOpen = (sid, i) => { const s = S.surveys.find(x => x.id === sid); const q = i != null ? s.questions[i] : null; qd = { sid, i: i ?? null, q: q ? q.q : '', type: q ? q.type : 'Multiple choice', options: q?.options ? [...q.options] : q ? [] : ['Yes, full GMC registration', 'Provisional registration', 'Not yet registered'], required: q ? q.required : true, tried: false }; drawQ(); };
  function drawQ() { const s = S.surveys.find(x => x.id === qd.sid); const bad = qd.tried && !qd.q.trim();
    App.dialog(`<div class="dlg-head"><div class="stack g4"><h2 id="dlg-title" class="h6" style="font-size:18px">${qd.i != null ? 'Edit survey question' : 'Add survey question'}</h2><span class="caption">${esc(s.name)} · question ${qd.i != null ? qd.i + 1 : s.questions.length + 1}</span></div><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>
      <div class="dlg-body"><div class="stack g4"><b class="body2">Question <span style="color:var(--error)">*</span></b>${App.field('', `<textarea rows="2" data-in="qd" placeholder="e.g. What is your current GMC registration status?" aria-label="Question">${esc(qd.q)}</textarea>`, { cls: 'multi ' + (bad ? 'err' : '') })}${bad ? '<p class="helper err">Write the question</p>' : ''}</div>
        <div class="g2"><div class="stack g4"><b class="body2">Answer type <span style="color:var(--error)">*</span></b>${App.select('', 'qd-type', ['Text', 'Yes / No', 'Multiple choice'], qd.type, { cls: 'sm' })}</div><div class="stack g4"><b class="body2">Template <span style="color:var(--error)">*</span></b>${App.select('', 'qd-sid', S.surveys.map(x => ({ v: x.id, t: x.name })), qd.sid, { cls: 'sm' })}</div></div>
        ${qd.type === 'Multiple choice' ? `<div class="subcard stack g8"><span class="body2">Answer options</span>${qd.options.map((o, i) => `<div class="opt-row"><i class="ri-draggable drag-handle"></i><input data-in="qd-opt" data-i="${i}" value="${esc(o)}" aria-label="Option ${i + 1}"><button class="icon-btn s20" data-act="qd-optx" data-i="${i}" aria-label="Remove option"><i class="ri-close-line"></i></button></div>`).join('')}<button class="linkish" data-act="qd-opt-add" style="align-self:flex-start">+ Add option</button></div>` : ''}
        <div class="toggle-card bordered"><div><b>Required</b><span class="caption">Candidates must answer before submitting</span></div>${App.sw(qd.required, 'data-ch="qd-req"', 'Required')}</div></div>
      <div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button>${qd.i == null ? '<button class="btn outlined lg" data-act="qd-go" data-again="1">Save &amp; add another</button>' : ''}<button class="btn primary lg" data-act="qd-go">Save question</button></div>`, { width: 560 }); }
  ins.qd = el => { qd.q = el.value; }; chs['qd-type'] = el => { qd.type = el.value; if (qd.type === 'Multiple choice' && !qd.options.length) qd.options = ['', '']; drawQ(); }; chs['qd-sid'] = el => { qd.sid = el.value; drawQ(); }; chs['qd-req'] = el => { qd.required = el.checked; };
  ins['qd-opt'] = el => { qd.options[+el.dataset.i] = el.value; }; acts['qd-optx'] = el => { qd.options.splice(+el.dataset.i, 1); drawQ(); }; acts['qd-opt-add'] = () => { qd.options.push(''); drawQ(); App.$$('[data-in=qd-opt]').pop().focus(); };
  acts['q-new'] = el => qOpen(el.dataset.id); acts['q-edit'] = el => qOpen(el.dataset.id, +el.dataset.i);
  acts['q-del'] = el => { const s = S.surveys.find(x => x.id === el.dataset.id); const [q] = s.questions.splice(+el.dataset.i, 1); App.render(); App.snack('Question deleted.', 'success', { label: 'Undo', fn: () => { s.questions.splice(+el.dataset.i, 0, q); App.render(); } }); };
  acts['qd-go'] = el => { if (!qd.q.trim()) { qd.tried = true; drawQ(); return; } const s = S.surveys.find(x => x.id === qd.sid); const q = { q: qd.q.trim(), type: qd.type, required: qd.required, options: qd.type === 'Multiple choice' ? qd.options.filter(o => o.trim()) : undefined };
    if (qd.i != null) s.questions[qd.i] = q; else s.questions.push(q); s.open = true; App.render(); App.snack('Question saved.'); if (el.dataset.again) qOpen(qd.sid); else App.closeModal(); };

  /* shared edit / delete */
  acts['cfg-edit'] = el => { const k = el.dataset.k, id = el.dataset.id; if (k === 'stage') H.addStage(id); if (k === 'reason') rrOpen(S.reasons.find(r => r.id === id)); if (k === 'skill') skOpen(S.skills.find(s => s.id === id)); };
  acts['cfg-del'] = el => { const k = el.dataset.k, id = el.dataset.id;
    if (k === 'stage') { const s = H.stage(id); const n = S.candidates.filter(c => c.stage === id).length; if (n) { App.snack(`“${s.name}” has ${n} candidate${n > 1 ? 's' : ''} — move them first, then delete it.`, 'error'); return; } if (S.stages.length < 3) { App.snack('A pipeline needs at least two stages.', 'error'); return; } const i = S.stages.indexOf(s); S.stages.splice(i, 1); App.render(); App.snack(`“${s.name}” deleted.`, 'success', { label: 'Undo', fn: () => { S.stages.splice(i, 0, s); App.render(); } }); }
    if (k === 'reason') { const i = S.reasons.findIndex(r => r.id === id); const [r] = S.reasons.splice(i, 1); App.render(); App.snack(`“${r.name}” deleted.`, 'success', { label: 'Undo', fn: () => { S.reasons.splice(i, 0, r); App.render(); } }); }
    if (k === 'skill') { const i = S.skills.findIndex(r => r.id === id); const [s] = S.skills.splice(i, 1); App.render(); App.snack(`“${s.name}” deleted.`, 'success', { label: 'Undo', fn: () => { S.skills.splice(i, 0, s); App.render(); } }); } };
})();
